{"content":"from .exceptions import InvalidTemperatureError, UnsupportedUnitError

def validate_temperature_value(value: str) -> float:
    """Validates that the input is a valid numeric temperature."""
    try:
        return float(value)
    except ValueError:
        raise InvalidTemperatureError(f"Invalid temperature value: '{value}'. Must be a number.")

def validate_unit(unit: str) -> str:
    """Validates that the input unit is either 'C' or 'F'."""
    unit = unit.upper()
    if unit not in ('C', 'F'):
        raise UnsupportedUnitError(f"Unsupported unit: '{unit}'. Use 'C' for Celsius or 'F' for Fahrenheit.")
    return unit
