{"path":"tempconv_cli/tests/test_validator.py","content":"import pytest
from tempconv.validator import validate_temperature_value, validate_unit
from tempconv.exceptions import InvalidTemperatureError, UnsupportedUnitError

def test_validate_temperature_value_valid():
    assert validate_temperature_value("100") == 100.0
    assert validate_temperature_value("-40.5") == -40.5

def test_validate_temperature_value_invalid():
    with pytest.raises(InvalidTemperatureError):
        validate_temperature_value("abc")

def test_validate_unit_valid():
    assert validate_unit("c") == "C"
    assert validate_unit("F") == "F"

def test_validate_unit_invalid():
    with pytest.raises(UnsupportedUnitError):
        validate_unit("K")
"}

